<?php require __DIR__.'/bootstrap.php';page_start('Гости — Tokyo Premium','Отзывы гостей ресторана Tokyo Premium. Публикуются после модерации.');header_html();$reviews=db()->query("SELECT guest_name,rating,body,created_at FROM reviews WHERE status='published' ORDER BY id DESC LIMIT 30")->fetchAll(); ?><main><section class="page-hero"><div class="kicker">Голоса гостей</div><h1>Впечатления, которыми делятся</h1><p>Публикуем отзывы после модерации. Мы не размещаем вымышленные цитаты.</p></section><section class="section"><div class="dish-grid"><?php foreach($reviews as $r): ?><article class="dish-card"><div class="dish-meta"><small><?=str_repeat('★',(int)$r['rating'])?></small><h3><?=e($r['guest_name'])?></h3><p><?=e($r['body'])?></p><small><?=e(substr($r['created_at'],0,10))?></small></div></article><?php endforeach ?><?php if(!$reviews): ?><p class="empty-state">Пока нет опубликованных отзывов. Будем рады прочитать ваш.</p><?php endif ?></div></section><section class="booking"><div><div class="kicker">Поделитесь впечатлением</div><h2>Ваш голос важен</h2><p>Отзыв появится на сайте после проверки командой ресторана.</p></div><form data-api="review"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label for="review-name">Имя</label><input id="review-name" name="name" maxlength="80" required></div><div class="field"><label for="rating">Оценка</label><select id="rating" name="rating"><option value="5">5 — превосходно</option><option value="4">4 — отлично</option><option value="3">3 — хорошо</option><option value="2">2 — есть замечания</option><option value="1">1 — неудовлетворительно</option></select></div><div class="field full"><label for="review-body">Отзыв</label><textarea id="review-body" name="body" minlength="20" maxlength="1000" required></textarea></div><div class="field"><label for="review-phone">Телефон для связи</label><input id="review-phone" name="phone" maxlength="30" required></div><button class="button" type="submit">Отправить отзыв ↗</button><div class="form-status" aria-live="polite"></div></form></section></main><?php footer_html(); ?>